BARTER_TRADERS = ["Todos", "Prapor", "Therapist", "Skier", "Peacekeeper", "Mechanic", "Ragman", "Jaeger", "Ref"]
BARTER_CATEGORIES = ["Todas", "Contenedor", "Llave / Tarjeta", "Blindaje / Casco", "Óptica / NVG", "Arma", "Equipo / Mods"]


def filter_barters(
    trader: str = "Todos",
    category: str = "Todas",
    only_essential: bool = False,
    max_ll: int = 4,
    query: str = "",
) -> List[Dict[str, Any]]:
    """Filtra el catálogo de trueques por Trader, Categoría, Loyalty Level máximo y búsqueda."""
    q = (query or "").strip().lower()
    results: List[Dict[str, Any]] = []
    for b in BARTERS_CATALOG:
        if trader and trader != "Todos" and b.get("trader") != trader:
            continue
        if category and category != "Todas" and b.get("category") != category:
            continue
        if only_essential and not b.get("is_essential"):
            continue
        if int(b.get("ll", 1) or 1) > max_ll:
            continue
        if q:
            hay = " ".join([
                b.get("reward", ""),
                b.get("inputs_text", ""),
                b.get("trader", ""),
                b.get("quest_unlock", ""),
            ]).lower()
            if q not in hay:
                continue
        results.append(b)
    return results


def check_item_keep_status(
    item_query: str,
    fir_items: List[Dict[str, Any]],
    hideout_modules: List[Dict[str, Any]],
    collector_items: List[str],
) -> Dict[str, Any]:
    """
    Semáforo táctico '¿Vender o Guardar?':
    Cruza un ítem de loot contra Quests FiR, Módulos del Hideout, Collector (Kappa) y Trueques clave.
    """
    q = (item_query or "").strip().lower()
    if len(q) < 2:
        return {
            "query": item_query,
            "verdict": "ESCRIBE UN ÍTEM (mín. 2 letras)",
            "level": "INFO",
            "quests": [],
            "hideout": [],
            "barters": [],
            "kappa": [],
        }

    matched_quests: List[Dict[str, Any]] = []
    for it in fir_items:
        name = str(it.get("item_name", ""))
        if q in name.lower():
            matched_quests.append({
                "item": name,
                "qty": it.get("amount", 1),
                "quest": it.get("quest_title", ""),
                "trader": it.get("trader_name", ""),
                "fir": bool(it.get("found_in_raid", 1)),
            })

    matched_hideout: List[Dict[str, Any]] = []
    for mod in hideout_modules:
        reqs = mod.get("requirements_lines", []) or []
        for req_line in reqs:
            if q in str(req_line).lower():
                matched_hideout.append({
                    "station": f"{mod.get('station_name', mod.get('station', ''))} Nv.{mod.get('level', 1)}",
                    "requirement": str(req_line),
                    "completed": bool(mod.get("is_completed", 0)),
                })

    matched_kappa = [k for k in collector_items if q in k.lower()]

    matched_barters: List[Dict[str, Any]] = []
    for b in BARTERS_CATALOG:
        if any(q in inp.get("name", "").lower() for inp in b.get("inputs", [])):
            matched_barters.append({
                "trader": f"{b['trader']} LL{b['ll']}",
                "reward": b["reward"],
                "inputs_text": b["inputs_text"],
                "is_essential": bool(b.get("is_essential")),
            })

    if matched_quests or matched_kappa:
        verdict = "🔴 NO VENDER — Requerido para Quests FiR / Kappa"
        level = "KEEP_FIR"
    elif matched_hideout:
        verdict = "🟡 GUARDAR PARA HIDEOUT — Requerido para mejorar estación"
        level = "KEEP_HIDEOUT"
    elif any(b["is_essential"] for b in matched_barters) or matched_barters:
        verdict = "🟢 ÚTIL EN TRUEQUES — Sirve para intercambios con Traders"
        level = "BARTER"
    else:
        verdict = "⚪ SEGURO PARA VENDER — Sin requisitos registrados con ese nombre"
        level = "SELL"

    return {
        "query": item_query,
        "verdict": verdict,
        "level": level,
        "quests": matched_quests[:25],
        "hideout": matched_hideout[:25],
        "barters": matched_barters[:25],
        "kappa": matched_kappa[:10],
    }
